//! End-to-end tests of the engine layer against a real libmpv, real media
//! files (generated by scripts/make-fixtures.sh) and a local HTTP server that
//! behaves like an IPTV provider. No window and no sound device are needed.
//!
//!   MPV_LIB=/path/to/libmpv  MPV_FIXTURES=../fixtures \
//!   cargo test -- --test-threads=1 --nocapture

mod support;

use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::time::{Duration, Instant};

use mpv_engine::{EndReason, Event, Library, Player, PlayerOptions, PropValue, SeekMode, TrackKind};
use support::Server;

fn library() -> Arc<Library> {
    static LIB: std::sync::OnceLock<Arc<Library>> = std::sync::OnceLock::new();
    LIB.get_or_init(|| match std::env::var("MPV_LIB") {
        Ok(path) => Library::open(path).expect("MPV_LIB"),
        Err(_) => Library::open_default().expect("libmpv not found: set MPV_LIB"),
    })
    .clone()
}

fn fixtures() -> PathBuf {
    std::env::var("MPV_FIXTURES").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../fixtures"))
}

fn player(untimed: bool) -> Player {
    let mut options = PlayerOptions { headless: true, hwdec: "no".into(), ..PlayerOptions::default() };
    if untimed {
        // As fast as the decoder allows, ignoring the clock.
        options.extra.push(("untimed".into(), "yes".into()));
    }
    Player::new(library(), &options).expect("player")
}

fn pump(player: &Player, timeout: Duration, mut done: impl FnMut(&Event) -> bool) -> Option<Event> {
    let end = Instant::now() + timeout;
    while Instant::now() < end {
        let event = player.next_event(0.1);
        if done(&event) {
            return Some(event);
        }
    }
    None
}

fn server() -> Server {
    Server::start(fixtures())
}

#[test]
fn missing_library_is_a_clean_error() {
    let err = Library::open("/nonexistent/libmpv-2.dll").err().expect("must fail");
    println!("error shown to the user: {err}");
    assert!(err.to_string().contains("could not be loaded"));
}

#[test]
fn can_decode_the_codecs_browsers_cannot() {
    let p = player(false);
    let (major, minor) = p.library().api_version();
    println!("libmpv {} (client API {major}.{minor})", p.version().unwrap_or_default());
    let decoders = p.decoders().expect("decoder list");
    for codec in ["h264", "hevc", "aac", "ac3", "eac3", "dts", "truehd", "vp9", "av1", "opus"] {
        let ok = decoders.iter().any(|d| d == codec);
        println!("  decoder {codec:<7} {}", if ok { "yes" } else { "MISSING" });
    }
    for codec in ["hevc", "ac3", "eac3", "dts"] {
        assert!(decoders.iter().any(|d| d == codec), "no {codec} decoder in this libmpv");
    }
}

#[test]
fn plays_each_codec_combination_to_the_end() {
    let srv = server();
    // What a browser does with each of them: plays, no sound, no picture, nothing.
    for (file, video, audio) in [("h264_aac.mkv", "h264", "aac"), ("h264_ac3.mkv", "h264", "ac3"), ("hevc_aac.mkv", "hevc", "aac"), ("hevc_eac3.mkv", "hevc", "eac3")] {
        let p = player(true);
        p.load(&srv.url(&format!("/files/{file}")), None).unwrap();
        assert!(pump(&p, Duration::from_secs(15), |e| *e == Event::FileLoaded).is_some(), "{file}: not loaded: {:?}", p.recent_logs());
        let tracks = p.tracks().unwrap();
        let v = tracks.iter().find(|t| t.kind == TrackKind::Video).and_then(|t| t.codec.clone());
        let a = tracks.iter().find(|t| t.kind == TrackKind::Audio).and_then(|t| t.codec.clone());
        println!("{file:<15} video={v:?} audio={a:?} duration={:?}", p.duration());
        assert_eq!(v.as_deref(), Some(video));
        assert_eq!(a.as_deref(), Some(audio));
        let duration = p.duration().unwrap_or(0.0);
        assert!((11.0..13.0).contains(&duration), "{file}: duration {duration}");

        let end = pump(&p, Duration::from_secs(60), |e| matches!(e, Event::EndFile { .. })).expect("no end-of-file event");
        assert_eq!(end, Event::EndFile { reason: EndReason::Eof, error: None }, "{file}: {:?}", p.recent_logs());
        let decode_errors = p.recent_logs().iter().filter(|l| l.contains("Error while decoding") || l.contains("decoding error")).count();
        assert_eq!(decode_errors, 0, "{file}: decode errors in {:?}", p.recent_logs());
    }
}

#[test]
fn follows_a_redirect_then_seeks_and_resumes() {
    let srv = server();
    let p = player(false);
    // Resume at 6 s, through an entry host that redirects to the node.
    p.load(&srv.url("/entry/h264_aac.mkv"), Some(6.0)).unwrap();
    assert!(pump(&p, Duration::from_secs(15), |e| *e == Event::PlaybackRestart).is_some(), "{:?}", p.recent_logs());
    p.pause(true).unwrap();
    let at = p.position().unwrap();
    println!("resumed at {at:.2} s (asked for 6.00)");
    assert!((5.0..7.5).contains(&at));
    assert!(!srv.requests_for("/entry/").is_empty() && !srv.requests_for("/files/h264_aac.mkv").is_empty(), "redirect not followed");

    p.seek(9.0, SeekMode::Absolute).unwrap();
    assert!(pump(&p, Duration::from_secs(10), |e| *e == Event::PlaybackRestart).is_some());
    let at = p.position().unwrap();
    println!("seeked to {at:.2} s (asked for 9.00)");
    assert!((8.0..10.5).contains(&at));
    let ranges: Vec<_> = srv.requests_for("/files/").into_iter().filter_map(|r| r.range).collect();
    println!("range requests seen by the provider: {ranges:?}");
    assert!(!ranges.is_empty(), "seeking did not use byte ranges");
}

#[test]
fn stopping_closes_the_connection_to_the_provider() {
    // Accounts allow a few simultaneous streams: a channel change must free the slot.
    let srv = server();
    let p = player(false);
    p.load(&srv.url("/slow/hevc4k_eac3.mkv"), None).unwrap();
    assert!(pump(&p, Duration::from_secs(20), |e| *e == Event::FileLoaded).is_some(), "{:?}", p.recent_logs());
    std::thread::sleep(Duration::from_millis(500));
    assert_eq!(srv.aborted.load(Ordering::SeqCst), 0);
    p.stop().unwrap();
    let end = Instant::now() + Duration::from_secs(5);
    while srv.aborted.load(Ordering::SeqCst) == 0 && Instant::now() < end {
        std::thread::sleep(Duration::from_millis(50));
    }
    println!("connections abandoned after stop(): {}", srv.aborted.load(Ordering::SeqCst));
    assert!(srv.aborted.load(Ordering::SeqCst) >= 1, "the provider connection stayed open after stop()");
}

#[test]
fn dropping_the_player_closes_the_connection_too() {
    let srv = server();
    {
        let p = player(false);
        p.load(&srv.url("/slow/hevc4k_eac3.mkv"), None).unwrap();
        assert!(pump(&p, Duration::from_secs(20), |e| *e == Event::FileLoaded).is_some());
    }
    let end = Instant::now() + Duration::from_secs(5);
    while srv.aborted.load(Ordering::SeqCst) == 0 && Instant::now() < end {
        std::thread::sleep(Duration::from_millis(50));
    }
    assert!(srv.aborted.load(Ordering::SeqCst) >= 1);
}

#[test]
fn a_refused_stream_reports_the_provider_status() {
    let srv = server();
    let p = player(false);
    p.load(&srv.url("/forbidden"), None).unwrap();
    let end = pump(&p, Duration::from_secs(15), |e| matches!(e, Event::EndFile { .. })).expect("no end-file");
    println!("event: {end:?}\nHTTP status read from the log: {:?}", p.last_http_status());
    assert!(matches!(end, Event::EndFile { reason: EndReason::Error, .. }));
    assert_eq!(p.last_http_status(), Some(403));
}

#[test]
fn hls_over_http_plays() {
    let srv = server();
    let p = player(true);
    p.load(&srv.url("/hls/index.m3u8"), None).unwrap();
    assert!(pump(&p, Duration::from_secs(15), |e| *e == Event::FileLoaded).is_some(), "{:?}", p.recent_logs());
    let duration = p.duration().unwrap_or(0.0);
    println!("HLS duration {duration:.1} s, tracks {:?}", p.tracks().unwrap().iter().map(|t| t.codec.clone()).collect::<Vec<_>>());
    assert!((10.0..14.0).contains(&duration));
    let end = pump(&p, Duration::from_secs(30), |e| matches!(e, Event::EndFile { .. })).unwrap();
    assert_eq!(end, Event::EndFile { reason: EndReason::Eof, error: None }, "{:?}", p.recent_logs());
}

#[test]
fn only_http_urls_are_accepted() {
    let p = player(false);
    for bad in ["file:///etc/passwd", "/etc/passwd", "ftp://example.com/a.mkv", "http://x/a\nloadfile /etc/passwd", "http://x/a b", "javascript:alert(1)", ""] {
        assert!(p.load(bad, None).is_err(), "accepted {bad:?}");
    }
    assert!(p.load(&format!("http://example.com/{}", "a".repeat(5000)), None).is_err());
}

/// Plays a hostile playlist to the end of its life and returns every event
/// kind seen plus the full log.
fn hostile(path: &str) -> (bool, Event, Vec<String>) {
    let srv = server();
    let p = player(false);
    p.load(&srv.url(path), None).unwrap();
    let mut loaded = false;
    let end = pump(&p, Duration::from_secs(15), |e| {
        loaded |= *e == Event::FileLoaded;
        matches!(e, Event::EndFile { reason, .. } if *reason != EndReason::Redirect)
    })
    .expect("no final end-file");
    // Let late log lines arrive.
    pump(&p, Duration::from_millis(500), |_| false);
    (loaded, end, p.recent_logs())
}

#[test]
fn a_playlist_cannot_make_the_player_read_local_files() {
    // 1. A local path ffmpeg would refuse for its extension anyway.
    let (loaded, end, logs) = hostile("/evil.m3u8");
    println!("evil.m3u8 -> loaded={loaded} end={end:?}\n{}", logs.join("\n"));
    assert!(!loaded, "a local file was played from a remote playlist");
    assert!(matches!(end, Event::EndFile { reason: EndReason::Error, .. }));

    // 2. A local path with an allowed extension, which does not exist: the
    //    answer must be "refused by the whitelist", not "no such file".
    let (loaded, end, logs) = hostile("/evil2.m3u8");
    println!("\nevil2.m3u8 -> loaded={loaded} end={end:?}\n{}", logs.join("\n"));
    assert!(!loaded);
    let text = logs.join("\n");
    assert!(text.contains("not on whitelist"), "file: was not stopped by the whitelist:\n{text}");
    assert!(!text.contains("No such file"), "the player actually tried to open the local file:\n{text}");
}

#[test]
fn properties_are_reported_as_events() {
    let srv = server();
    let p = player(false);
    p.load(&srv.url("/files/h264_aac.mkv"), None).unwrap();
    let (mut duration, mut time) = (None, None);
    pump(&p, Duration::from_secs(10), |e| {
        if let Event::Property { name, value: PropValue::Double(v) } = e {
            match name.as_str() {
                "duration" => duration = Some(*v),
                "time-pos" => time = Some(*v),
                _ => {}
            }
        }
        duration.is_some() && time.is_some()
    });
    println!("observed duration={duration:?} time-pos={time:?}");
    assert!(duration.is_some() && time.is_some());
    p.pause(true).unwrap();
    let paused = pump(&p, Duration::from_secs(3), |e| matches!(e, Event::Property { name, value: PropValue::Bool(true) } if name == "pause"));
    assert!(paused.is_some(), "no pause event");
}

#[test]
fn audio_tracks_can_be_listed_and_switched() {
    let srv = server();
    let p = player(false);
    p.load(&srv.url("/files/multi_audio.mkv"), None).unwrap();
    assert!(pump(&p, Duration::from_secs(10), |e| *e == Event::FileLoaded).is_some());
    let audio: Vec<_> = p.tracks().unwrap().into_iter().filter(|t| t.kind == TrackKind::Audio).collect();
    println!("audio tracks: {:?}", audio.iter().map(|t| (t.id, t.lang.clone(), t.selected)).collect::<Vec<_>>());
    assert_eq!(audio.len(), 2);
    assert_eq!(audio[0].lang.as_deref(), Some("eng"));
    assert_eq!(audio[1].lang.as_deref(), Some("fra"));
    assert_eq!(p.selected("aid"), Some(audio[0].id));
    p.select_audio(Some(audio[1].id)).unwrap();
    assert_eq!(p.selected("aid"), Some(audio[1].id));
    p.select_audio(None).unwrap();
    assert_eq!(p.selected("aid"), None);
}

#[test]
fn creating_and_destroying_players_repeatedly_is_stable() {
    let srv = server();
    let lib = library();
    for _ in 0..25 {
        let p = Player::new(lib.clone(), &PlayerOptions { headless: true, hwdec: "no".into(), ..PlayerOptions::default() }).unwrap();
        p.load(&srv.url("/files/h264_aac.mkv"), None).unwrap();
        pump(&p, Duration::from_secs(5), |e| *e == Event::FileLoaded).expect("file loaded");
    }
}

#[test]
#[ignore = "heavy: decodes 8 s of 4K HEVC in software; run with --ignored"]
fn four_k_hevc_with_eac3_decodes_in_software() {
    let srv = server();
    let p = player(true);
    let started = Instant::now();
    p.load(&srv.url("/files/hevc4k_eac3.mkv"), None).unwrap();
    let end = pump(&p, Duration::from_secs(180), |e| matches!(e, Event::EndFile { .. })).expect("no end-file");
    let took = started.elapsed().as_secs_f64();
    println!("8 s of 4K HEVC + E-AC3 decoded in {took:.1} s -> {:.2}x real time (this machine)", 8.0 / took);
    assert_eq!(end, Event::EndFile { reason: EndReason::Eof, error: None });
}

#[test]
fn video_margins_and_diagnostic_properties() {
    let srv = server();
    let p = player(false);
    // Out of range and non-finite values are clamped, not rejected.
    p.set_video_margins(0.1, 0.1, 0.2, f64::NAN).unwrap();
    p.set_video_margins(5.0, -1.0, 0.0, 0.3).unwrap();
    assert_eq!(p.property("video-margin-ratio-left").as_deref().map(|v| v.starts_with("0.95")), Some(true));

    p.load(&srv.url("/files/hevc_eac3.mkv"), None).unwrap();
    assert!(pump(&p, Duration::from_secs(10), |e| *e == Event::FileLoaded).is_some());
    let (v, a) = (p.property("video-format"), p.property("audio-codec-name"));
    println!("video-format={v:?} audio-codec-name={a:?} hwdec-current={:?} container-fps={:?}", p.property("hwdec-current"), p.property("container-fps"));
    assert_eq!(v.as_deref(), Some("hevc"));
    assert_eq!(a.as_deref(), Some("eac3"));
}

#[test]
fn open_first_lists_every_attempt() {
    let err = Library::open_first(&[PathBuf::from("/nope/libmpv-2.dll"), PathBuf::from("/also/missing/libmpv-2.dll")]).err().unwrap().to_string();
    println!("{err}");
    assert!(err.contains("/nope/") && err.contains("/also/missing/"));
    assert!(Library::open_first(&[]).is_err());
}
